import { NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth/next"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    const session = await getServerSession(authOptions)

    if (!session) {
      return NextResponse.json(
        { error: "Non authentifié" },
        { status: 401 }
      )
    }

    if (session.user.role !== "CLIENT") {
      return NextResponse.json(
        { error: "Accès refusé - Clients uniquement" },
        { status: 403 }
      )
    }

    const userId = parseInt(session.user.id)
    const client = await prisma.client.findUnique({
      where: { userId }
    })

    if (!client) {
      return NextResponse.json(
        { error: "Profil client non trouvé" },
        { status: 404 }
      )
    }

    // Récupérer toutes les commandes du client
    const orders = await prisma.order.findMany({
      where: { clientId: client.id },
      include: {
        product: {
          include: {
            images: true,
            seller: {
              include: {
                user: true
              }
            }
          }
        }
      },
      orderBy: {
        created_at: 'desc'
      }
    })

    console.log(` ${orders.length} commandes trouvées pour le client ${client.id}`)

    return NextResponse.json({
      success: true,
      orders: orders.map(order => ({
        id: order.id,
        quantity: order.quantity,
        totalPrice: order.totalPrice,
        status: order.status,
        paymentStatus: order.paymentStatus,
        created_at: order.created_at,
        updated_at: order.updated_at,
        product: {
          id: order.product.id,
          name: order.product.name,
          price: order.product.price,
          images: order.product.images,
          seller: {
            business_name: order.product.seller.business_name,
            user: {
              username: order.product.seller.user.username
            }
          }
        }
      }))
    })

  } catch (error) {
    console.error("Erreur lors de la récupération des commandes:", error)
    return NextResponse.json(
      { error: "Erreur interne du serveur" },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    // Compter le nombre de tailleurs
    const sellerCount = await prisma.seller.count()

    // Récupérer quelques exemples
    const sellers = await prisma.seller.findMany({
      take: 5,
      include: {
        user: true
      }
    })

    return NextResponse.json({
      count: sellerCount,
      examples: sellers
    })
  } catch (error) {
    console.error('Erreur:', error)
    return NextResponse.json(
      { error: 'Erreur serveur' },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    // Récupérer toutes les catégories, matériaux, tailles et couleurs existants
    const [categories, materials, sizes, colors] = await Promise.all([
      prisma.category.findMany({ orderBy: { name: 'asc' } }),
      prisma.material.findMany({ orderBy: { name: 'asc' } }),
      prisma.size.findMany({ orderBy: { name: 'asc' } }),
      prisma.color.findMany({ orderBy: { name: 'asc' } })
    ])

    return NextResponse.json({
      categories: categories.map(c => ({ label: c.name, value: c.name })),
      materials: materials.map(m => ({ label: m.name, value: m.name })),
      sizes: sizes.map(s => ({ label: s.name, value: s.name })),
      colors: colors.map(c => ({ label: c.name, value: c.name }))
    })
  } catch (error) {
    console.error('Erreur lors de la récupération des filtres produits:', error)
    return NextResponse.json(
      { error: 'Erreur serveur' },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    // Récupérer les valeurs uniques depuis les tailleurs existants
    const sellers = await prisma.seller.findMany({
      select: {
        servicesOffered: true,
        yearsOfExperience: true,
        companyType: true,
        companyCity: true,
        user: {
          select: {
            address: true
          }
        }
      }
    })

    // Extraire les valeurs uniques
    const services = [...new Set(sellers
      .map(s => s.servicesOffered)
      .filter(Boolean)
    )]

    const cities = [...new Set([
      ...sellers.map(s => s.companyCity).filter(Boolean),
      ...sellers.map(s => s.user.address).filter(Boolean)
    ])]

    // Toujours retourner les filtres de base, même sans données
    return NextResponse.json({
      services: [
        { label: 'Retouches', value: 'alterations' },
        { label: 'Confection sur mesure', value: 'custom' },
        { label: 'Réparations', value: 'repairs' },
        { label: 'Tous services', value: 'all' }
      ],
      experiences: [
        { label: '1-3 ans', value: '1-3' },
        { label: '3-5 ans', value: '3-5' },
        { label: '5-10 ans', value: '5-10' },
        { label: '10+ ans', value: '10+' }
      ],
      types: [
        { label: 'Particulier', value: 'individual' },
        { label: 'Professionnel', value: 'professional' }
      ],
      cities: cities.length > 0 ? cities.map(c => ({ label: c, value: c })) : [
        { label: 'Paris', value: 'Paris' },
        { label: 'Lyon', value: 'Lyon' },
        { label: 'Marseille', value: 'Marseille' },
        { label: 'Toulouse', value: 'Toulouse' }
      ]
    })
  } catch (error) {
    console.error('Erreur lors de la récupération des filtres tailleurs:', error)
    return NextResponse.json(
      { error: 'Erreur serveur' },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"

export async function GET() {
  try {
    // Compter combien il y a de sellers professionnels vs particuliers
    const totalSellers = await prisma.seller.count()
    const professionalSellers = await prisma.seller.count({
      where: {
        companyType: { not: null }
      }
    })
    const individualSellers = totalSellers - professionalSellers

    console.log(`Total sellers: ${totalSellers}, Professional: ${professionalSellers}, Individual: ${individualSellers}`)

    // Retourner seulement le filtre type pro/amateur qui existe vraiment
    return NextResponse.json({
      types: [
        { 
          label: `Particulier (${individualSellers})`, 
          value: 'individual' 
        },
        { 
          label: `Professionnel (${professionalSellers})`, 
          value: 'professional' 
        }
      ]
    })
  } catch (error) {
    console.error('Erreur lors de la récupération des filtres tailleurs:', error)
    return NextResponse.json(
      { error: 'Erreur serveur' },
      { status: 500 }
    )
  }
}

