import { type NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function PUT(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const session = await getServerSession(authOptions)

        if (!session?.user || session.user.role !== "SELLER") {
            return NextResponse.json({ error: "Non autorisé" }, { status: 401 })
        }

        const sellerId = session.user.seller?.id
        if (!sellerId) {
            return NextResponse.json({ error: "ID du vendeur manquant" }, { status: 400 })
        }

        const resolvedParams = await params
        const projectId = parseInt(resolvedParams.id)
        if (isNaN(projectId)) {
            return NextResponse.json({ error: "ID de projet invalide" }, { status: 400 })
        }

        const { status } = await request.json()

        // Vérifier que le statut est valide
        const validStatuses = ["pending", "accepted", "in_progress", "completed", "cancelled"]
        if (!validStatuses.includes(status)) {
            return NextResponse.json(
                { error: "Statut invalide" },
                { status: 400 }
            )
        }

        // Vérifier que le seller a une proposition acceptée pour ce projet
        const project = await prisma.project.findFirst({
            where: {
                id: projectId,
                proposals: {
                    some: {
                        sellerId: sellerId,
                        status: "accepted",
                    },
                },
            },
            include: {
                proposals: {
                    where: {
                        sellerId: sellerId,
                        status: "accepted",
                    },
                },
            },
        })

        if (!project) {
            return NextResponse.json(
                { error: "Projet non trouvé ou vous n'avez pas de proposition acceptée" },
                { status: 404 }
            )
        }

        // Mettre à jour le statut du projet
        const updatedProject = await prisma.project.update({
            where: {
                id: projectId,
            },
            data: {
                status: status,
                updated_at: new Date(),
            },
        })

        return NextResponse.json({
            success: true,
            project: {
                id: updatedProject.id,
                status: updatedProject.status,
                updated_at: updatedProject.updated_at,
            },
        })
    } catch (error) {
        console.error("Erreur lors de la mise à jour du statut:", error)
        return NextResponse.json(
            { error: "Erreur lors de la mise à jour du statut", detail: (error as Error).message },
            { status: 500 }
        )
    }
}

import { type NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET(request: NextRequest) {
    try {
        const session = await getServerSession(authOptions)

        if (!session?.user || session.user.role !== "SELLER") {
            return NextResponse.json({ error: "Non autorisé" }, { status: 401 })
        }

        const sellerId = session.user.seller?.id
        if (!sellerId) {
            return NextResponse.json({ error: "ID du vendeur manquant" }, { status: 400 })
        }

        // Récupérer les projets liés à une proposition acceptée par ce vendeur
        const projects = await prisma.project.findMany({
            where: {
                proposals: {
                    some: {
                        sellerId: sellerId,
                        status: "accepted",
                    },
                },
            },
            include: {
                client: {
                    include: {
                        user: {
                            select: {
                                username: true,
                                email: true,
                            },
                        },
                    },
                },
                proposals: {
                    where: {
                        sellerId: sellerId,
                        status: "accepted",
                    },
                    select: {
                        price: true,
                        updated_at: true, // à défaut de acceptedAt qui n’existe pas
                    },
                },
            },
            orderBy: {
                updated_at: "desc",
            },
        })

        // Formater les données
        const formattedProjects = projects.map((project) => ({
            id: project.id,
            title: project.title,
            description: project.description,
            deadline: project.deadline,
            status: project.status,
            created_at: project.created_at,
            updated_at: project.updated_at,
            client: {
                username: project.client.user.username,
                email: project.client.user.email,
            },
            acceptedProposal: project.proposals[0] || null,
        }))

        return NextResponse.json(formattedProjects)
    } catch (error) {
        console.error("Erreur lors de la récupération des projets:", error)
        return NextResponse.json(
            { error: "Erreur lors de la récupération des projets", detail: (error as Error).message },
            { status: 500 }
        )
    }
}

import { type NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET(request: NextRequest) {
    try {
        const session = await getServerSession(authOptions)

        if (!session?.user || session.user.role !== "SELLER") {
            return NextResponse.json({ error: "Non autorisé" }, { status: 401 })
        }

        const sellerId = session.user.seller?.id
        if (!sellerId) {
            return NextResponse.json({ error: "ID du vendeur manquant" }, { status: 400 })
        }

        // Récupérer tous les projets où ce vendeur a fait une proposition
        const projects = await prisma.project.findMany({
            where: {
                proposals: {
                    some: {
                        sellerId: sellerId,
                    },
                },
            },
            include: {
                client: {
                    include: {
                        user: {
                            select: {
                                username: true,
                                email: true,
                            },
                        },
                    },
                },
                proposals: {
                    where: {
                        sellerId: sellerId,
                    },
                    select: {
                        id: true,
                        price: true,
                        message: true,
                        status: true,
                        created_at: true,
                        updated_at: true,
                    },
                },
            },
            orderBy: {
                updated_at: "desc",
            },
        })

        // Formater les données avec la logique de statut appropriée
        const formattedProjects = projects.map((project) => {
            const myProposal = project.proposals[0] // Il ne devrait y avoir qu'une seule proposition par vendeur par projet

            // Déterminer le statut affiché selon la logique métier
            let displayStatus = "pending"

            if (myProposal.status === "rejected") {
                displayStatus = "cancelled"
            } else if (myProposal.status === "pending") {
                displayStatus = "pending"
            } else if (myProposal.status === "accepted") {
                // Si la proposition est acceptée, regarder le statut du projet
                if (project.status === "pending") {
                    displayStatus = "accepted"
                } else if (project.status === "in_progress") {
                    displayStatus = "in_progress"
                } else if (project.status === "completed") {
                    displayStatus = "completed"
                } else {
                    displayStatus = "accepted"
                }
            }

            return {
                id: project.id,
                title: project.title,
                description: project.description,
                deadline: project.deadline,
                status: displayStatus,
                projectStatus: project.status, // Statut original du projet
                proposalStatus: myProposal.status, // Statut original de la proposition
                created_at: project.created_at,
                updated_at: project.updated_at,
                client: {
                    username: project.client.user.username,
                    email: project.client.user.email,
                },
                myProposal: {
                    id: myProposal.id,
                    price: myProposal.price,
                    message: myProposal.message,
                    status: myProposal.status,
                    created_at: myProposal.created_at,
                    updated_at: myProposal.updated_at,
                },
            }
        })

        return NextResponse.json(formattedProjects)
    } catch (error) {
        console.error("Erreur lors de la récupération des projets:", error)
        return NextResponse.json(
            { error: "Erreur lors de la récupération des projets", detail: (error as Error).message },
            { status: 500 }
        )
    }
}

import { NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth/next"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session || session.user.role !== "SELLER") {
      return NextResponse.json(
        { error: "Non autorisé" },
        { status: 401 }
      )
    }

    // Récupérer l'ID du seller
    const seller = await prisma.seller.findUnique({
      where: { userId: session.user.id }
    })

    if (!seller) {
      return NextResponse.json(
        { error: "Profil vendeur non trouvé" },
        { status: 404 }
      )
    }

    // Récupérer les produits du vendeur
    const products = await prisma.product.findMany({
      where: {
        sellerId: seller.id
      },
      include: {
        images: true,
        category: true,
        material: true,
        size: true,
        color: true,
        stockBySize: true
      },
      orderBy: {
        created_at: 'desc'
      }
    })

    return NextResponse.json({
      success: true,
      products
    })

  } catch (error) {
    console.error("Erreur lors de la récupération des produits:", error)
    return NextResponse.json(
      { error: "Erreur interne du serveur" },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth/next"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session || session.user.role !== "SELLER") {
      return NextResponse.json(
        { error: "Non autorisé" },
        { status: 401 }
      )
    }

    // Convertir l'ID utilisateur de string vers number
    const userId = parseInt(session.user.id)
    if (isNaN(userId)) {
      return NextResponse.json(
        { error: "ID utilisateur invalide" },
        { status: 400 }
      )
    }

    // Récupérer l'ID du seller
    const seller = await prisma.seller.findUnique({
      where: { userId: userId }
    })

    if (!seller) {
      return NextResponse.json(
        { error: "Profil vendeur non trouvé" },
        { status: 404 }
      )
    }

    // Récupérer les produits du vendeur
    const products = await prisma.product.findMany({
      where: {
        sellerId: seller.id
      },
      include: {
        images: true,
        category: true,
        material: true,
        size: true,
        color: true,
        stockBySize: true
      },
      orderBy: {
        created_at: 'desc'
      }
    })

    return NextResponse.json({
      success: true,
      products
    })

  } catch (error) {
    console.error("Erreur lors de la récupération des produits:", error)
    return NextResponse.json(
      { error: "Erreur interne du serveur" },
      { status: 500 }
    )
  }
}

"use client"

import type React from "react"

import { useState } from "react"
