                                <SelectItem value="sarl">SARL</SelectItem>
                                <SelectItem value="sas">SAS</SelectItem>
                                <SelectItem value="eurl">EURL</SelectItem>
                                <SelectItem value="ei">Entreprise Individuelle</SelectItem>
                              </SelectContent>
                            </Select>
